entries[1235959] = { ["name"] = "Mage Spellslinger 11.2 Class Set 2pc", ["text"] = "Arcane\nArcane Blast damage increased by 12% and Arcane Blast grants 1 stack of Arcane Harmony. Direct Splinter damage has a 25% chance to grant a stack of Arcane Harmony.\n\nFire, Frost\nIce Lance and Icicle damage increased by 10% and Ice Lance has a 50% chance to generate 1 stack of Cold Front. Direct Splinter damage has a 15% chance to grant a stack of Cold Front." }
entries[1235962] = { ["name"] = "Mage Sunfury 11.2 Class Set 2pc", ["text"] = "Arcane, Fire, Frost\nSpellfire Sphere spell damage bonus increased by 1.0%. Mana Cascade now grants an additional 0.5% Haste per stack." }
entries[1235963] = { ["name"] = "Mage Frostfire 11.2 Class Set 2pc", ["text"] = "Fire\nComet Storm and Frostfire Burst damage increased by 15%. Frostfire Bolt damage increased by 8%. Comet Storm, Frostfire Burst, and Frostfire Bolt now apply Ignite at 75% effectiveness.\n\nArcane, Frost\nMeteor and Frostfire Burst damage increased by 30%. Frostfire Bolt damage increased by 10%. Meteor, Frostfire Burst, and Frostfire Bolt now apply Ignite, dealing an additional 25% damage over 9 sec." }
entries[1235964] = { ["name"] = "Mage Spellslinger 11.2 Class Set 4pc", ["text"] = "Arcane\nSplinter damage increased by 8%. Arcane Orb has a 100% chance to grant a stack of Arcane Harmony, up to 8 times. Upon reaching 20 stacks of Arcane Harmony, gain Intuition at 100% effectiveness.\n\nFire\nSplinter damage increased by 8%. Arcane Orb has a 100% chance to grant a stack of Arcane Harmony, up to 8 times. When Cold Front summons a Frozen Orb, increase your spell damage by 8% for 10 sec.\n\nFrost\nWhen Frozen Orb deals damage to one or more enemies, it has a 15% chance to grant a stack of Cold Front. When Cold Front summons a Frozen Orb, increase your spell damage by 8% for 10 sec.\n\n(100ms cooldown)" }
entries[1235965] = { ["name"] = "Mage Sunfury 11.2 Class Set 4pc", ["text"] = "Fire, Frost\nExceptional spells cast by your Phoenix adds an additional 0.3 sec to the duration of your next Hyperthermia. When your Phoenix expires, it empowers you even further beyond, granting Lesser Time Warp and 10% increased spell damage for 10 sec.\n\nArcane\nExceptional spells cast by your Phoenix adds an additional 0.5 sec to the duration of your next Arcane Soul. When your Phoenix expires, it empowers you even further beyond, granting Lesser Time Warp and 20% increased spell damage for 10 sec." }
entries[1235966] = { ["name"] = "Mage Frostfire 11.2 Class Set 4pc", ["text"] = "Arcane, Frost\nCasting Glacial Spike has a 100% chance to also cast a Pyroblast, dealing (352.5% of Spell Power) Fire damage. Additionally, Pyroblast now benefits from Ignite.\n\nFire\nCasting Pyroblast has a 20% chance to also cast a Glacial Spike dealing (366.24% of Spell Power) Frost damage. Glacial Spikes cast this way don't root. Additionally, Glacial Spike now benefits from Ignite." }
