entries[1236054] = { ["name"] = "Enchant Chest - Mark of Nalorakk", ["text"] = "2 sec cast 2\nRequires Chest, Chest\nTools: Runed Enchanting Rod\nReagents:\nMote of Wild Magic (5), Majestic Claw , Petrified Root (2), Eversinging Dust (15), Radiant Shard (10), Dawn Crystal (2)\nOptional Reagents:\nPermanently enchants chest armor with Mark of Nalorakk, increasing Strength by 32 and Stamina by 93. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nTreasure:\nChest of Proven Valor\nZone:\nDen of Nalorakk\n\nEnchant Chest - Mark of Nalorakk\n\nUse: Permanently enchants chest armor with Mark of Nalorakk, increasing Strength by 32 and Stamina by 93. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\n70" }
entries[1236055] = { ["name"] = "Enchant Helm - Hex of Leeching", ["text"] = "2 sec cast\nRequires Helms\nTools: Runed Enchanting Rod\nReagents:\nEversinging Dust (15), Radiant Shard (3)\nOptional Reagents:\nPermanently enchants helm armor with Hex of Leeching, increasing Leech by 22. Cannot be applied to items lower than level 120.\n\nAmani Augments - Berserker Brawn\nProfession Trainer:\nMidnight Enchanting (35)\nCost:\n140\n\nEnchant Helm - Hex of Leeching\n\nUse: Permanently enchants helm armor with Hex of Leeching, increasing Leech by 22. Cannot be applied to items lower than level 120.\n\nAmani Augments - Berserker Brawn\n70" }
entries[1236056] = { ["name"] = "Enchant Helm - Empowered Hex of Leeching", ["text"] = "2 sec cast 2\nRequires Helms\nTools: Runed Enchanting Rod\nReagents:\nMote of Wild Magic (20), Petrified Root (2), Eversinging Dust (20), Radiant Shard (10), Dawn Crystal (2)\nOptional Reagents:\nPermanently enchants helm armor with Empowered Hex of Leeching, increasing Leech by 44. Also heals you for 2% Health whenever you defeat a foe outdoors in a Midnight zone once per 5 sec. Cannot be applied to items lower than level 120.\n\nAmani Augments - Berserker Brawn\nDrop:\nHeavy Trunk\nZone:\nDelves\n\nEnchant Helm - Empowered Hex of Leeching\n\nUse: Permanently enchants helm armor with Empowered Hex of Leeching, increasing Leech by 44. Also heals you for 2% Health whenever you defeat a foe outdoors in a Midnight zone once per 5 sec. Cannot be applied to items lower than level 120.\n\nAmani Augments - Berserker Brawn\n70" }
entries[1236057] = { ["name"] = "Enchant Boots - Lynx's Dexterity", ["text"] = "2 sec cast\nRequires Boots\nTools: Runed Enchanting Rod\nReagents:\nMote of Wild Magic (10), Carving Canine , Petrified Root (2), Eversinging Dust (15), Radiant Shard (3), Dawn Crystal\nOptional Reagents:\nPermanently enchants boots with Lynx's Dexterity, increasing Avoidance by 15 and Stamina by 186. Cannot be applied to items lower than level 120.\n\nAmani Augments - Berserker Brawn\nSpecialization:\nElevating Equipment - Berserker Brawn\n\nEnchant Boots - Lynx's Dexterity\n\nUse: Permanently enchants boots with Lynx's Dexterity, increasing Avoidance by 15 and Stamina by 186. Cannot be applied to items lower than level 120.\n\nAmani Augments - Berserker Brawn\n70" }
entries[1236058] = { ["name"] = "Enchant Ring - Amani Mastery", ["text"] = "2 sec cast\nRequires Ring\nTools: Runed Enchanting Rod\nReagents:\nEversinging Dust (5)\nOptional Reagents:\nPermanently enchants a ring with Amani Mastery, increasing Mastery by 22. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nProfession Trainer:\nMidnight Enchanting (45)\nCost:\n160\n\nEnchant Ring - Amani Mastery\n\nUse: Permanently enchants a ring with Amani Mastery, increasing Mastery by 22. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\n70" }
entries[1236059] = { ["name"] = "Enchant Ring - Eyes of the Eagle", ["text"] = "2 sec cast\nRequires Ring\nTools: Runed Enchanting Rod\nReagents:\nMote of Wild Magic (15), Peerless Plumage (2), Petrified Root (2), Eversinging Dust (15), Radiant Shard (3), Dawn Crystal\nOptional Reagents:\nPermanently enchants a ring with Eyes of the Eagle, increasing critical strike effectiveness by 1%. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\nDrop:\nZul'Aman Treasures\n\nEnchant Ring - Eyes of the Eagle\n\nUse: Permanently enchants a ring with Eyes of the Eagle, increasing critical strike effectiveness by 1%. Cannot be applied to items lower than level 120.\n\nAmani Augments - Zul'Aman Zeal\n70" }
