entries[1236126] = { ["name"] = "Binding Javelin", ["text"] = "100 yd range\nInstant\nTaah'bat launches arcane javelins at targeted players, inflicting 2424449 Arcane damage to players within 8 yards of the targets and tethering all players struck.\n\nEach tether inflicts 606112 Arcane damage every 1 sec and reduces their movement speed by 50%, increasing in intensity every 5 seconds until the javelin is destroyed. This effect stacks." }
