entries[1236332] = { ["name"] = "Druid Elune's Chosen 11.2 Class Set 2pc", ["text"] = "Balance\nStarfire damage increased by 15%. Gaining Astral Power with Starfire has a 40% chance to launch a Starsurge at a victim at 45% effectiveness.\n\nFeral, Guardian, Restoration\nThrash damage increased by 20%. Thrash has a 40% chance to launch a Starsurge at a victim at 160% effectiveness.\n\n(100ms cooldown)" }
entries[1236333] = { ["name"] = "Druid Elune's Chosen 11.2 Class Set 4pc", ["text"] = "Balance\nOn impact, Starsurges launched by Starfire split to up to 3 additional targets at 40% effectiveness and grant a stack of Gathering Moonlight. Casting Fury of Elune or Full Moon consumes Gathering Moonlight to increase your damage by 4% per stack for 12 sec.\n\nFeral, Guardian, Restoration\nOn impact, Starsurges launched by Thrash split to up to 3 additional targets at 20% effectiveness and grant a stack of Gathering Moonlight. Casting Lunar Beam consumes Gathering Moonlight to increase your damage by 4% per stack for 12 sec." }
entries[1236334] = { ["name"] = "Druid Keeper of the Grove 11.2 Class Set 2pc", ["text"] = "Balance, Feral, Guardian\nCasting Celestial Alignment calls upon the assistance of a dryad for 10 sec that casts Starsurge at 360% effectiveness and Starfall at 800% effectiveness.\n\nRestoration\nCasting Incarnation: Tree of Life or Convoke the Spirits calls upon the assistance of a dryad for 5 sec that casts Tranquility at 50% effectiveness and instantly Regrowths your lowest health ally at 200% effectiveness." }
entries[1236336] = { ["name"] = "Druid Keeper of the Grove 11.2 Class Set 4pc", ["text"] = "Balance, Feral, Guardian\nWhen your Dryad fades, your next 2 Starsurges damage for an additional amount equal to 3% of your damage done while it was active and splash 10% of their damage onto nearby enemies, reduced beyond 5 targets.\n\nRestoration\nWhen your Dryad fades, your next 2 Swiftmends heal for an additional amount equal to 5% of your healing done while it was active and splash 25% of their healing onto nearby allies, reduced beyond 5 targets." }
entries[1236337] = { ["name"] = "Druid Wildstalker 11.2 Class Set 2pc", ["text"] = "Feral\nThe rate at which Bloodseeker Vines grow is increased by 40%. Tiger's Fury causes Bloodseeker Vines to grow on up to 3 valid nearby enemies.\n\nBalance, Guardian, Restoration\nThe rate at which Symbiotic Blooms grow is increased by 45%. Casting Regrowth with Clearcasting causes Symbiotic Blooms to grow on up to 2 valid nearby allies." }
entries[1236338] = { ["name"] = "Druid Wildstalker 11.2 Class Set 4pc", ["text"] = "Feral\nBloodseeker Vines have a 20% chance to trigger Bursting Growth every 2 sec at 100% effectiveness. Each stack of Bloodseeker Vines on an enemy increases Bursting Growth damage taken by 40%.\n\nBalance, Guardian, Restoration\nSymbiotic Blooms have a 35% chance to trigger Bursting Growth every 2 sec at 100% effectiveness. Each stack of Symbiotic Blooms on an ally increases Bursting Growth healing taken by 30%." }
entries[1236342] = { ["name"] = "Preparing to Strike", ["text"] = "Instant\nFeral\nRavage has a 40% chance to make you Ravage your target again 4 sec later at 100% of the initial power.\n\nBalance, Guardian, Restoration\nRavage has a 40% chance to make you Ravage your target again 4 sec later at 60% effectiveness." }
